import { useEffect, useState } from "react";
import axios from "axios";
import { useNavigate } from "react-router-dom";
import "../styles/ProfilePage.css";

function formatDate(d) {
  const dt = typeof d === "string" ? new Date(d) : d;
  return dt.toLocaleDateString(undefined, { day: "2-digit", month: "2-digit" });
}

export function ProfilePage() {
  const navigate = useNavigate();
  const [loading, setLoading] = useState(true);
  const [user, setUser] = useState(null);
  const [recentLookups, setRecentLookups] = useState([]);
  const [error, setError] = useState(null);

  useEffect(() => {
    const token = localStorage.getItem("token");
    if (!token) {
      setError("You must log in first.");
      setLoading(false);
      return;
    }

    // Gọi song song 2 API: /auth/me và /api/dict/recent
    Promise.all([
      axios.get("http://localhost:3030/auth/me", {
        headers: { Authorization: `Bearer ${token}` },
      }),
      axios.get("http://localhost:3030/api/dict/recent", {
        headers: { Authorization: `Bearer ${token}` },
      }),
    ])
      .then(([userRes, lookupRes]) => {
        setUser(userRes.data);
        setRecentLookups(lookupRes.data || []);
      })
      .catch((err) => {
        console.error("Profile fetch error:", err);
        setError("Failed to load profile data.");
      })
      .finally(() => setLoading(false));
  }, []);

  if (loading) return <p className="muted">Loading profile...</p>;
  if (error) return <p className="muted">{error}</p>;
  if (!user) return <p className="muted">No user data available.</p>;

  return (
    <div className="profile-page">
      {/* Header */}
      <div className="profile-header">
        <h2>👤 {user.username || "User"}'s Profile</h2>
        <button className="back-button" onClick={() => navigate("/chat")}>
          ← Back to Chat
        </button>
      </div>

      {/* Basic Info */}
      <section className="section card">
        <h3 className="section-title">Basic Info</h3>
        <div className="grid-2">
          <div>
            <div className="field">
              <span className="label">User name:</span>{" "}
              <span>{user.username}</span>
            </div>
            <div className="field">
              <span className="label">Email:</span> <span>{user.email}</span>
            </div>
          </div>
          <div>
            <div className="hint">
              ⚠️ Không nên lưu/hiển thị mật khẩu thật dưới dạng plain-text trong
              sản phẩm production.
            </div>
          </div>
        </div>
      </section>

      {/* Recent Lookups */}
      <section className="section card">
        <h3 className="section-title">Recent Lookups (7 days)</h3>
        {recentLookups.length ? (
          <ul className="list">
            {recentLookups.map((w, i) => (
              <li key={i} className="list-row">
                <span className="badge">{w.word}</span>
                <span className="muted">{formatDate(w.at || w.createdAt)}</span>
              </li>
            ))}
          </ul>
        ) : (
          <p className="muted">No lookups yet.</p>
        )}
      </section>
    </div>
  );
}
